export interface PackageItineraryDay {
  day: number
  title: string
  description: string
  activities: string[]
  meals: string
  accommodation: string
  elevation?: string
  distance?: string
  highlight?: string
  image: string
}

/**
 * Per-vehicle pricing grid (whole-group package price by vehicle and hotel
 * category). Used for the South India packages where the client supplies a
 * per-car rate card rather than a single per-person price.
 */
export interface VehiclePricingRow {
  vehicle: string
  prices: number[]
}

export interface VehiclePricing {
  categories: string[]
  rows: VehiclePricingRow[]
  note?: string
}

export interface Package {
  title: string
  slug: string
  destinationName: string
  destinationSlug: string
  category: "leisure" | "adventure" | "educational"
  description: string
  heroImage: string
  images: string[]
  duration: { days: number; nights: number }
  price: number
  discountedPrice?: number
  difficulty: "Easy" | "Moderate" | "Challenging"
  groupSize: { min: number; max: number }
  rating: number
  reviewCount: number
  inclusions: string[]
  exclusions: string[]
  highlights: string[]
  featured: boolean
  itinerary: PackageItineraryDay[]
  /** Optional per-vehicle rate card (South India packages). */
  vehiclePricing?: VehiclePricing
  /**
   * Optional honest-disclosure note shown prominently on the package page —
   * pricing basis, seasonal advisories, local taxi clarifications, what's a
   * group vs private departure, etc. Client wants transparency on every page.
   */
  transparencyNote?: string
  /**
   * Optional richer "experience storytelling" intro that replaces a dry tour
   * summary with a more evocative, branded narrative (e.g. Leh expedition
   * framing). Rendered above the day-by-day itinerary when present.
   */
  experienceStory?: string
  /**
   * Optional seasonal advisory list — month-by-month or condition notes
   * (road closures, snow, monsoon, permit windows).
   */
  seasonalAdvisories?: string[]
}

